method.description:
Returns the currently loaded music data.

[b]Returns:[/b] SiONData object or null if no data is loaded

[b]Example:[/b]
[codeblock]
var driver = SiONDriver.create()
add_child(driver)

var mml = "t120 l8 cdefgab>c"
var data = driver.compile(mml)

# Get the loaded data
var current_data = driver.get_data()
if current_data:
	print("Data is loaded")
[/codeblock]
